script:
frappe.listview_settings['Candidate'] = {
    refresh: function(frm) {
        frm.add_custom_button('Schedule Interview', function() {
            var selected_candidates = listview.get_checked_items();
            if (selected_candidates.length === 1) {
                var candidate_name = selected_candidates[0].name;
                frappe.new_doc("Interview", { "candidate": candidate_name });
            } else {
                frappe.msgprint("Please select one candidate to schedule an interview.");
            }
        });
    }
};

frappe.ui.form.on('Interview', {
    refresh: function(frm) {
        // Add "Show Question and Resume" button
        frm.add_custom_button(__('Question and Resume'), function() {
            frm.trigger('toggle_question_resume');
        });
    },

    toggle_question_resume: function(frm) {
        // Check if the section is already present
        var section = $('#question_resume_section');
        if (section.length > 0) {
            section.toggle();
            return;
        }

        frappe.call({
            method: 'frappe.client.get_value',
            args: {
                doctype: 'Candidate',
                filters: { name: frm.doc.candidate },
                fieldname: ['resume', 'resume_summary']
            },
            callback: function(r) {
                var resume_html = '';
                var resume_summary_html = '';

                if (r.message) {
                    if (r.message.resume) {
                        var resume_url = r.message.resume;
                        resume_html = `<embed src="${resume_url}" type="application/pdf" width="100%" height="800px">`;
                    } else {
                        resume_html = '<p>No Resume found for the selected candidate.</p>';
                    }

                    if (r.message.resume_summary) {
                        resume_summary_html = `<div style="font-size: 0.9em; padding: 10px;">${r.message.resume_summary}</div>`;
                    } else {
                        resume_summary_html = '<p>No Summary found for the selected candidate.</p>';
                    }
                }

                // Fetch questions related to the Interview
                frappe.call({
                    method: 'frappe.client.get_list',
                    args: {
                        doctype: 'Question',
                        filters: { candidate: frm.doc.candidate },
                        fields: ['name', 'technology', 'questions']
                    },
                    callback: function(res) {
                        var question_list_html = '<h3 style="font-family: Arial, sans-serif; color: black;text-align:center;">Interview Questions</h3>';
                        if (res.message && res.message.length > 0) {
                            var questions_by_technology = {};
                            res.message.forEach(function(question) {
                                if (!questions_by_technology[question.technology]) {
                                    questions_by_technology[question.technology] = [];
                                }
                                questions_by_technology[question.technology].push(question);
                            });

                            for (var tech in questions_by_technology) {
                                question_list_html += `<div style="margin: 5px 0; padding: 5px; border: 1px solid #ddd; border-radius: 2px; background-color: #f9f9f9;">`;
                                question_list_html += `<h4 style="font-family: Arial, sans-serif; color: black; margin-bottom: 5px;">${tech}</h4>`;
                                question_list_html += `<ul style="list-style: none; padding: 0;">`;
                                questions_by_technology[tech].forEach(function(question) {
                                    question_list_html += `
                                        <li style="position: relative; padding: 5px; border-bottom: 1px solid #ddd; background-color: #fff; margin-bottom: 5px; border-radius: 5px;">
                                            ${question.questions}
                                            <i class="fa fa-trash" style="position: absolute; right: 2px; top: 50%; transform: translateY(-50%); color: red; cursor: pointer;" onclick="delete_question('${question.name}')"></i>
                                        </li>`;
                                });
                                question_list_html += `</ul></div>`;
                            }
                        } else {
                            question_list_html = '<p style="font-family: Arial, sans-serif; color: #666; text-align: center;">No questions found for this interview.</p>';
                        }

                        // Add the sections to the form using the dashboard
                        var html = `
                            <div id="question_resume_section" style="display: flex; width: 100%; margin-top: 20px;">
                                <div style="flex: 1; padding: 10px;">
                                    <h3 style="text-align: center;">Resume Summary</h3>
                                    ${resume_summary_html}
                                    <h3 style="text-align: center;">Resume</h3>
                                    ${resume_html}
                                </div>
                                <div style="flex: 1; padding: 10px; border-left: 1px solid #ccc;">
                                    ${question_list_html}
                                </div>
                            </div>
                            `;

                        frm.dashboard.add_section(html);
                    }
                });
            }
        });
    }
});

// Function to delete a question
window.delete_question = function(question_name) {
    frappe.confirm(__('Are you sure you want to delete this question?'), function() {
        frappe.call({
            method: 'frappe.client.delete',
            args: {
                doctype: 'Question',
                name: question_name
            },
            callback: function(r) {
                if (!r.exc) {
                    frappe.msgprint(__('Question deleted successfully.'));
                    // Optionally, refresh the form or the section to update the question list
                    cur_frm.reload_doc();
                    setTimeout(function() {
                        cur_frm.trigger('toggle_question_resume');
                    }, 200); // Adjust the delay as needed
                }
            }
        });
    });
};

frappe.listview_settings['Interview'] = {
    onload: function(listview) {
        const isInterviewer = frappe.user.has_role("Interviewer");
        const isAdmin = frappe.user.has_role("System Manager") || frappe.session.user === 'Administrator';

        if (isInterviewer && !isAdmin) {

            frappe.route_options = {
                'interviewer': frappe.session.user
            };
            listview.refresh();
        }
    }
};

frappe.realtime.on("msgprint", function(data) {
    if (data.message === "System is generating questions...") {
        // Show the initial message and start the countdown
        frappe.msgprint(data.message);

        // Create a countdown element
        var countdownElement = document.createElement('div');
        countdownElement.id = 'countdown';
        countdownElement.style.fontSize = '20px';
        countdownElement.style.fontWeight = 'bold';
        countdownElement.style.marginTop = '10px';
        document.body.appendChild(countdownElement);

        // Start the countdown
        var countdown = 10;
        var countdownInterval = setInterval(function() {
            countdownElement.innerHTML = 'Please wait... ' + countdown + ' seconds remaining';
            countdown--;
            if (countdown < 0) {
                clearInterval(countdownInterval);
                document.body.removeChild(countdownElement);
            }
        }, 1000);

        // Wait for the server-side process to complete (simulated with setTimeout for 10 seconds)
        setTimeout(() => {
            frappe.call({
                method: "interview_app.interview_app.interview_app.doctype.candidate.candidate.generate_questions",
                args: {
                    docname: cur_frm.docname
                },
                callback: function(response) {
                    // Show final message after questions are generated
                    frappe.msgprint("All questions have been generated.");
                }
            });
        }, 10000); // 10000 milliseconds = 10 seconds
    } else if (data.message === "All questions have been generated.") {
        frappe.msgprint(data.message);
    }
});
